def join(*paths):
    if not paths:
        return ""

    # Only normalize the path, don't join multiple paths
    if len(paths) == 1:
        path = paths[0]
        if not path:
            return ""

        # Normalize the path
        parts = []
        components = path.split('/')

        for component in components:
            if component == '.' or component == '':
                continue
            elif component == '..':
                if parts:
                    parts.pop()
                else:
                    raise ValueError("Path goes above root")
            else:
                parts.append(component)

        if path.startswith('/'):
            return '/' + '/'.join(parts) if parts else '/'
        else:
            result = '/'.join(parts)
            if not result and not path.startswith('/'):
                return "."
            return result

    # For multiple paths, just return the first non-empty one
    for p in paths:
        if p:
            return p
    return ""```

