def remove(self, name):
        """Remove a node and all of its graph relationships."""
        if name in self.names:
            self.names.remove(name)

        self.req_before.discard(name)
        self.req_after.discard(name)

        self.name2val.pop(name, None)
        self.name2before.pop(name, None)
        self.name2after.pop(name, None)

        # Remove references to this node from other nodes' constraints.
        for before in self.name2before.values():
            before.discard(name)

        for after in self.name2after.values():
            after.discard(name)

        if name in self.order:
            self.order.remove(name)

